function longest_streak(days) {
  const present = new Set(days);
  let best = 0;
  for (const d of present) {
    if (!present.has(d - 1)) {
      let length = 1;
      while (present.has(d + length)) length++;
      best = Math.max(best, length);
    }
  }
  return best;
}

